output_text:
[
  {
    "id": "no_cart_in_single_file_aisle",
    "text": "Shopping carts are prohibited in single-file aisles where the horizontal clearance is only one cell wide.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_pushing_cart_into_single_file_aisle",
    "text": "An agent must not push a cart from a wider passage into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "only_park_cart_at_aisle_mouth",
    "text": "A cart may only be set down at the mouth of a single-file product aisle.",
    "abstraction": {
      "state_properties": {
        "cartPark": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "cartPark"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart at a single-file aisle mouth, the agent is obliged to retrieve the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "cartPark": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "cartPark",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "cartPark",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "return_to_cart_after_single_file_shelf",
    "text": "After taking an item from a shelf inside a single-file aisle, the agent must return to the aisle mouth and pick up the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfCell": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        },
        "cartPark": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "singleFileShelfService": {
          "pre": {
            "and": [
              "singleFileShelfCell",
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "cartPark",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "singleFileShelfService",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "no_cartless_walking_in_public_aisles",
    "text": "Except in the entrance area, a single-file aisle, or its cart-parking mouth, the agent should not walk around without the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartPark": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartlessAllowedArea": {
          "or": [
            "singleFileAisle",
            "cartPark",
            "entranceCartArea"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessAllowedArea"
          }
        ]
      }
    }
  },
  {
    "id": "use_cart_at_accessible_shelves",
    "text": "When interacting with a shelf from a cart-accessible aisle, the agent must have the cart with them.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartAccessibleShelfCell": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfCell",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_cart_before_shopping",
    "text": "At the start of the trip, the agent is obliged to obtain a cart before completing the shopping run.",
    "abstraction": {
      "state_properties": {
        "cartPossessed": "hasCart"
      },
      "events": {
        "takeCart": {
          "pre": "INTERACT",
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cartPossessed"
    }
  }
]
